descriptor.templateCss:
.dg-pwr-card {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #a855f7;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.card-header-pwr {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.title-pwr {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.icon-pwr { font-size: 16px; }
.badge-pwr {
  font-size: 11px;
  font-weight: 700;
  color: #a855f7;
  border: 1.5px solid #a855f7;
  background: rgba(168, 85, 247, 0.1);
  padding: 2px 10px;
  border-radius: 20px;
}
.pwr-split-body {
  display: flex;
  justify-content: space-around;
  align-items: center;
  margin: 6px 0;
}
.pwr-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}
.pwr-sub { font-size: 10px; font-weight: 700; color: #94a3b8; letter-spacing: 0.5px; }
.pwr-main { display: flex; align-items: baseline; gap: 4px; }
.pwr-num { font-size: 32px; font-weight: 800; line-height: 1; }
.pwr-num.kva { color: #a855f7; }
.pwr-num.kvar { color: #c084fc; }
.pwr-unit { font-size: 15px; font-weight: 600; color: #94a3b8; }
.pwr-tag { font-size: 11px; color: #64748b; }
.pwr-tag strong { color: #e2e8f0; }
.pwr-sep { width: 1px; height: 45px; background: rgba(148, 163, 184, 0.15); }
.pwr-bar-track {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
  overflow: hidden;
  margin: 2px 0;
}
.pwr-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #a855f7 0%, #38bdf8 100%);
  border-radius: 3px;
  transition: width 0.4s ease;
}
.card-footer-pwr {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 6px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var kva = 0.0, kvar = 0.0;
  var nominalKva = 250.0;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('aparente') !== -1 || k.indexOf('kva') !== -1 || i === 0) kva = v;
          else if (k.indexOf('reactiva') !== -1 || k.indexOf('kvar') !== -1 || i === 1) kvar = v;
        }
      }
    }
  }

  // Cálculo de kW y FP: P = sqrt(S^2 - Q^2)
  var kw = 0.0;
  var pf = 1.0;
  if (kva > 0.5) {
    var pSquared = Math.max(0, Math.pow(kva, 2) - Math.pow(kvar, 2));
    kw = Math.sqrt(pSquared);
    pf = Math.min(1.0, kw / kva);
  }

  var loadPct = Math.min(100, Math.max(0, (kva / nominalKva) * 100));
  var container = self.ctx.$container ? self.ctx.$container[0] : null;

  if (container) {
    var elKva = container.querySelector('#kva-val');
    var elKvar = container.querySelector('#kvar-val');
    if (elKva) elKva.textContent = kva.toFixed(1);
    if (elKvar) elKvar.textContent = Math.abs(kvar).toFixed(1);

    var elPct = container.querySelector('#kva-pct-lbl');
    if (elPct) elPct.textContent = loadPct.toFixed(0) + '%';

    var elBar = container.querySelector('#pwr-bar-fill');
    if (elBar) elBar.style.width = loadPct + '%';

    var elKw = container.querySelector('#kw-estimated-lbl');
    if (elKw) elKw.innerHTML = 'Pot. Activa: <strong style="color:#f1f5f9;">' + kw.toFixed(1) + ' kW</strong>';

    var elBadge = container.querySelector('#pf-badge');
    if (elBadge) {
      if (kva < 0.5) {
        elBadge.textContent = 'STANDBY';
      } else {
        elBadge.textContent = 'FP: ' + pf.toFixed(2) + ' (' + (kvar >= 0 ? 'IND' : 'CAP') + ')';
      }
    }

    var elReg = container.querySelector('#q-regime-lbl');
    if (elReg) {
      elReg.textContent = kvar > 0.5 ? 'Inductivo' : (kvar < -0.5 ? 'Capacitivo' : 'Equilibrado');
    }
  }
};
self.onDestroy = function() {};
